#!/usr/bin/env python3
"""Rewrite module docstrings on C3DC/GC tests (test steps only, no Katalon paths)."""
from __future__ import annotations

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from Commons import action_log  # noqa: E402

DOC_RE = re.compile(r'^(""".*?""")\s*\n', re.S | re.M)
HEADER_RE = re.compile(
    r"^# GENERATED by Tools/generate_tests\.py.*\n|^# Originally generated by Tools/generate_tests\.py.*\n"
)
NEW_HEADER = (
    "# Originally generated by Tools/generate_tests.py. "
    "Edit freely; re-running the generator skips edited files.\n"
)
FILTER_RE = re.compile(r'\.select_filter\("([^"]+)",\s*"([^"]+)"\)')


def _facet_label(group: str) -> str:
    raw = action_log.filter_facet_display(group)
    return re.sub(r"Facet$", "", raw)


def build_docstring(source: str) -> str:
    if "verify_static_data" in source and "select_filter" not in source:
        gotos = re.findall(r'\.goto\("([^"]+)"\)', source)
        if gotos:
            extra = ", ".join(gotos)
            return (
                f"Verify static page content on the home page, {extra}, "
                "and other pages listed in the test."
            )
        return "Verify static page content on the pages exercised in this test."

    if "open_explore" in source:
        opener = "Open Explore"
    elif "open_data" in source:
        opener = "Open Data"
    else:
        opener = None

    phrases: list[str] = []
    for group, value in FILTER_RE.findall(source):
        if "Accession" in group:
            phrases.append(f"study {value}")
        else:
            phrases.append(f"{_facet_label(group)} {action_log.filter_subfilter_display(group)} {value}")

    parts: list[str] = []
    if opener:
        parts.append(opener)
    if phrases:
        tail = "select " + " and ".join(phrases)
        parts.append(tail if not opener else tail)
    sentence = ", ".join(parts) if parts else "Run explore filters"

    if "read_statbar" in source or "verify_tab" in source:
        sentence += ", then compare stat bar and all result tabs to Memgraph queries"
    sentence += "."
    return sentence


def rewrite_file(path: Path) -> bool:
    text = path.read_text()
    doc = build_docstring(text)
    new_block = f'"""{doc}"""\n\n'
    if DOC_RE.search(text):
        text = DOC_RE.sub(new_block, text, count=1)
    else:
        m = re.match(r"((?:#.*\n)*)", text)
        prefix = m.group(1) if m else ""
        rest = text[len(prefix) :]
        text = prefix + new_block + rest
    text = HEADER_RE.sub(NEW_HEADER, text)
    if path.read_text() == text:
        return False
    path.write_text(text)
    return True


def main() -> int:
    updated = 0
    for app in ("C3DC", "GC"):
        base = ROOT / "Testcases" / app
        for path in sorted(base.rglob("test_*.py")):
            if rewrite_file(path):
                updated += 1
                print(path.relative_to(ROOT))
    print(f"Updated {updated} file(s)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
